import { atom, read, update } from 'claude-code'
import type { EngineInterface, PluginOptions, Register, RenderSurface, Timer } from 'claude-code'

import type { PultServer } from '../types'
import { areaOf, areasFrom, parseAreas } from './areas'
import { daysBetween, parseDeadlines } from './deadlines'
import { isOwnRole, parseDuties } from './duties'
import {
  EMPTY_TOKENS, addTokens, amount, bottomLine, contextLine, days, ddmm, forecast, hhmm, limitLine,
  localDate, localStamp, norm, placeOf, shortLabel, span, sparkline, toUsage,
} from './format'
import { setLanguage, t } from './i18n'
import { offline, parseProbe, probeArgv, sshError } from './server'
import { cacheSvg, limitsSvg, serverSvg, sessionSvg } from './svg'

const PANE = 'pult'
const CACHE_MS = 60 * 60_000
const WARN_BEFORE_MS = 10 * 60_000
const PING_EVERY_MS = 55 * 60_000
const BIG_CONTEXT = 150_000
const LONG_SESSION = 15
const AFTER_RESET_MS = 60_000
const RETRY_MS = 60_000
const STAGGER_MS = 3 * 60_000
const SERVER_SHOWN_MS = 60_000
const SERVER_IDLE_MS = 120_000
const SHOWN_DEADLINES = 6

// Everything personal comes from the options; an empty option turns its feature off
const cfg = {
  quick: [] as string[],
  vault: '',
  focus: '',
  deadlines: '',
  deadlinesNote: '',
  inbox: '',
  inboxDir: '',
  journal: '',
  obsidian: '',
  areasRoot: '',
  host: '',
  serverName: '',
  shell: 'sh',
}

const usage = atom({ plugin: 'pult', key: 'usage' } as const, null)
const samples = atom({ plugin: 'pult', key: 'samples' } as const, [])
const turns = atom({ plugin: 'pult', key: 'turns' } as const, 0)
const tools = atom({ plugin: 'pult', key: 'tools' } as const, 0)
const tokens = atom({ plugin: 'pult', key: 'tokens' } as const, EMPTY_TOKENS)
const agentTokens = atom({ plugin: 'pult', key: 'agentTokens' } as const, EMPTY_TOKENS)
const history = atom({ plugin: 'pult', key: 'history' } as const, [])
const lastTurnAt = atom({ plugin: 'pult', key: 'lastTurnAt' } as const, 0)
const nowAtom = atom({ plugin: 'pult', key: 'now' } as const, 0)
const keepUntil = atom({ plugin: 'pult', key: 'keepUntil' } as const, 0)
const resumeAt = atom({ plugin: 'pult', key: 'resumeAt' } as const, 0)
const journalPath = atom({ plugin: 'pult', key: 'journalPath' } as const, '')
const server = atom({ plugin: 'pult', key: 'server' } as const, null)
const isPolling = atom({ plugin: 'pult', key: 'isPolling' } as const, false)
const deadline = atom({ plugin: 'pult', key: 'deadline' } as const, null)
const areas = atom({ plugin: 'pult', key: 'areas' } as const, [])
const waiting = atom({ plugin: 'pult', key: 'waiting' } as const, '')
const inbox = atom({ plugin: 'pult', key: 'inbox' } as const, 0)
const area = atom({ plugin: 'pult', key: 'area' } as const, '')
const areaList = atom({ plugin: 'pult', key: 'areaList' } as const, [])
const duties = atom({ plugin: 'pult', key: 'duties' } as const, [])
const isDutiesOpen = atom({ plugin: 'pult', key: 'isDutiesOpen' } as const, false)

let place = ''
let here = ''
let cwd = ''
let isPaneOpen = false
let retries = 0
let warnTimer: Timer | undefined
let pingTimer: Timer | undefined
let resumeTimer: Timer | undefined

// Surfaces where the engine raises PromptHint; elsewhere the usage line lives in the band
const hintSurfaces = new Set<RenderSurface>()

const dayTone = (n: number) => (n <= 3 ? { color: 'red' } : n <= 10 ? { color: 'yellow' } : { dimColor: true as const })
const isAbsolute = (p: string): boolean => /^([A-Za-z]:[\\/]|\/|~)/.test(p)
const isWindows = (): boolean => /^[A-Za-z]:[\\/]/.test(cwd)

function configure(options: PluginOptions): void {
  const opt = (key: string): string => String(options[key] ?? '').trim()
  setLanguage(opt('language'))
  cfg.quick = (opt('quickReplies') || t.quickReplies).split('|').map(s => s.trim()).filter(Boolean).slice(0, 9)
  cfg.vault = norm(opt('vaultPath'))
  const inVault = (p: string): string => (p === '' ? '' : isAbsolute(p) ? norm(p) : cfg.vault === '' ? '' : `${cfg.vault}/${norm(p).replace(/^\/+/, '')}`)
  cfg.focus = inVault(opt('focusNote'))
  cfg.deadlinesNote = opt('deadlinesNote')
  cfg.deadlines = inVault(cfg.deadlinesNote)
  cfg.inboxDir = opt('inboxDir')
  cfg.inbox = inVault(cfg.inboxDir)
  cfg.journal = inVault(opt('journalDir'))
  cfg.obsidian = opt('obsidianVault')
  cfg.areasRoot = norm(opt('areasRoot'))
  cfg.host = opt('sshHost')
  cfg.serverName = opt('serverName') || 'Server'
  cfg.shell = opt('serverShell') === 'powershell' ? 'powershell' : 'sh'
}

// Open a link or start a terminal the way the machine does it
function opener(target: string): string[] {
  if (isWindows()) return ['explorer.exe', target]
  return cwd.startsWith('/Users/') ? ['open', target] : ['xdg-open', target]
}

function terminalArgv(): string[] {
  if (isWindows()) return ['cmd.exe', '/c', 'start', cfg.serverName, 'ssh', cfg.host]
  if (cwd.startsWith('/Users/')) return ['osascript', '-e', `tell application "Terminal" to do script "ssh ${cfg.host}"`]
  return ['x-terminal-emulator', '-e', 'ssh', cfg.host]
}

// --- server -----------------------------------------------------------------

async function pollServer($: EngineInterface, isForced: boolean): Promise<void> {
  if (cfg.host === '' || (await read($, isPolling))) return
  // A background run (claude -p, routines) attaches no surface: nobody looks, no ssh.
  // isInteractive will not do: the desktop app starts the engine as a host, and it is false there too
  if (!isForced && (await $.session.surfaces()).length === 0) return
  const now = await $.clock.now()
  const every = isPaneOpen ? SERVER_SHOWN_MS : SERVER_IDLE_MS
  const mine = await read($, server)
  if (!isForced && mine !== null && now - mine.checkedAt < every - 5_000) return
  // A fresh snapshot from another session saves an ssh call
  const key = `pult-server:${cfg.host}`
  const shared = (await $.store.get(key)) as PultServer | undefined
  if (!isForced && shared !== undefined && now - shared.checkedAt < every - 5_000) {
    if (mine === null || shared.checkedAt > mine.checkedAt) await update($, server, () => shared)
    return
  }
  await update($, isPolling, () => true)
  let fresh: PultServer
  try {
    const ran = await $.process.run(probeArgv(cfg.host, cfg.shell), { timeoutMs: 20_000 })
    fresh = parseProbe(ran.stdout, now) ?? offline(now, sshError(ran.stderr))
  } catch {
    fresh = offline(now, 'no answer in 20 s')
  }
  await update($, server, () => fresh)
  await update($, isPolling, () => false)
  await $.store.set(key, fresh)
}

// --- notes: focus, deadlines table, inbox ------------------------------------------

async function readText($: EngineInterface, path: string): Promise<string> {
  if (path === '') return ''
  try {
    return await $.fs.read(path)
  } catch {
    return ''
  }
}

async function refreshNotes($: EngineInterface): Promise<void> {
  const today = localDate(await $.clock.now())
  const text = await readText($, cfg.focus)
  const table = await readText($, cfg.deadlines)
  const codes = (await read($, areaList)).map(a => a.code)
  const parsed = parseAreas(text, today, codes)
  const mine = parseDuties(table, today)
  // The band shows the earliest date from the focus note and the table
  const candidates = [parseDeadlines(text, today)[0], mine[0] && { date: mine[0].date, label: mine[0].what }].filter(d => d !== undefined)
  const nearest = candidates.sort((a, b) => a.date.localeCompare(b.date))[0] ?? null
  if (JSON.stringify(await read($, areas)) !== JSON.stringify(parsed.areas)) await update($, areas, () => parsed.areas)
  if ((await read($, waiting)) !== parsed.waiting) await update($, waiting, () => parsed.waiting)
  if (JSON.stringify(await read($, deadline)) !== JSON.stringify(nearest)) await update($, deadline, () => nearest)
  if (JSON.stringify(await read($, duties)) !== JSON.stringify(mine)) await update($, duties, () => mine)
  if (cfg.inbox !== '') {
    try {
      const count = (await $.fs.list(cfg.inbox)).filter(f => f.kind === 'file' && f.name.endsWith('.md')).length
      if ((await read($, inbox)) !== count) await update($, inbox, () => count)
    } catch {
      // no folder, nothing to count
    }
  }
}

async function refreshAreas($: EngineInterface): Promise<void> {
  if (cfg.areasRoot === '') return
  try {
    const found = areasFrom((await $.fs.list(cfg.areasRoot)).filter(f => f.kind === 'dir').map(f => f.name))
    if (JSON.stringify(await read($, areaList)) !== JSON.stringify(found)) await update($, areaList, () => found)
  } catch {
    // no folder, no areas
  }
}

// --- journal -----------------------------------------------------------------

async function saveJournal($: EngineInterface): Promise<string | undefined> {
  if (cfg.journal === '') {
    $.ui.toast(t.journalOff)
    return undefined
  }
  const r = await $.model.fork({ prompt: t.journalAsk, maxTokens: 1500 })
  if (!r.isAnswered) {
    $.ui.toast(t.journalFailed)
    return undefined
  }
  const stamp = localStamp(await $.clock.now())
  const title = (r.text.match(/^#\s*(.+)$/m) ?? [])[1]?.trim() ?? 'session'
  const slug = title.toLowerCase().replace(/[^a-zа-яё0-9]+/gi, '-').replace(/^-|-$/g, '').slice(0, 50)
  const path = `${cfg.journal}/${stamp.slice(0, 10)}-${slug}.md`
  const front = `---\ncreated: ${stamp.slice(0, 10)}\ntime: '${stamp.slice(11, 16)}'\ntype: session-log\n---\n`
  await $.fs.write(path, front + r.text.trim() + '\n')
  await update($, journalPath, () => path)
  $.ui.toast(t.journalWritten(path.split('/').pop() ?? path))
  return path
}

// --- prompt cache ------------------------------------------------------------

function rearmWarn($: EngineInterface): void {
  warnTimer?.cancel()
  warnTimer = $.clock.after(CACHE_MS - WARN_BEFORE_MS, async () => {
    const { context } = await $.session.usage()
    if ((context.tokens ?? 0) < BIG_CONTEXT) return
    if ((await $.clock.now()) < (await read($, keepUntil))) return
    $.ui.toast(t.cacheSoon(amount(context.tokens ?? 0)))
  })
}

function startPing($: EngineInterface): void {
  pingTimer?.cancel()
  pingTimer = $.clock.every(PING_EVERY_MS, async () => {
    if ((await $.clock.now()) > (await read($, keepUntil))) {
      pingTimer?.cancel()
      pingTimer = undefined
      return
    }
    // A question over the cached conversation: reading the cache extends its life
    await $.model.fork({ prompt: 'Reply with a single dot.', maxTokens: 5 })
  })
}

async function keepCache($: EngineInterface, hours: number): Promise<string> {
  const until = (await $.clock.now()) + hours * 3_600_000
  await update($, keepUntil, () => until)
  startPing($)
  return t.keptReply(hhmm(until))
}

async function releaseCache($: EngineInterface): Promise<void> {
  pingTimer?.cancel()
  pingTimer = undefined
  await update($, keepUntil, () => 0)
}

// --- resume after a limit ----------------------------------------------------

function scheduleResume($: EngineInterface, at: number, wait: number, text: string): void {
  resumeTimer?.cancel()
  void update($, resumeAt, () => at)
  resumeTimer = $.clock.after(wait, () => {
    resumeTimer = undefined
    void update($, resumeAt, () => 0)
    void $.prompt.submit({ text })
  })
}

async function cancelResume($: EngineInterface): Promise<void> {
  resumeTimer?.cancel()
  resumeTimer = undefined
  await update($, resumeAt, () => 0)
}

// Several sessions on one limit wake up in turn, not all in the same minute
async function slotFor($: EngineInterface, resets: string): Promise<number> {
  const id = await $.session.id()
  const queue = ((await $.store.get('pult-resume-queue')) ?? []) as { id: string; resetsAt: string }[]
  const others = queue.filter(x => x.resetsAt === resets && x.id !== id)
  await $.store.set('pult-resume-queue', [...others, { id, resetsAt: resets }])
  return others.length
}

// --- registration --------------------------------------------------------------

async function openPane($: EngineInterface): Promise<boolean> {
  const opened = await $.ui.open({ id: PANE, title: t.title })
  isPaneOpen = opened.isPlaced
  return opened.isPlaced
}

export const register: Register = (on, options) => {
  configure(options)

  on('session.start', async ($, e, next) => {
    await update($, isPolling, () => false)
    cwd = e.cwd
    place = placeOf(e.cwd, cfg.areasRoot)
    here = areaOf(e.cwd, cfg.areasRoot)
    if ((await read($, area)) === '' && here !== '') await update($, area, () => here)
    const now = await $.clock.now()
    await update($, nowAtom, () => now)
    const first = await $.session.usage()
    await update($, usage, prev => toUsage(first, prev))

    await $.command.register({ name: 'pult', description: t.cmdPult })
    await $.command.register({ name: 'journal', description: t.cmdJournal })
    await $.command.register({ name: 'keep-cache', description: t.cmdKeep })

    // Timers live until the module reloads; what was promised before it is armed again
    const resume = await read($, resumeAt)
    if (resume > now) scheduleResume($, resume, resume - now, t.resumeText)
    if ((await read($, keepUntil)) > now) startPing($)
    if ((await read($, lastTurnAt)) > 0) rearmWarn($)

    $.clock.every(60_000, async () => {
      const tick = await $.clock.now()
      await update($, nowAtom, () => tick)
      if (Math.floor(tick / 60_000) % 10 === 0) await refreshNotes($)
    })
    $.clock.every(30_000, () => void pollServer($, false))
    void refreshAreas($).then(() => refreshNotes($))
    void pollServer($, false)
    void openPane($)
    return next(e)
  })

  on('session.measure', async ($, e, next) => {
    const result = await next(e)
    await update($, usage, prev => toUsage(e, prev))
    return result
  })

  on('tool.call', async ($, e, next) => {
    await update($, tools, n => n + 1)
    return next(e)
  })

  on('turn.complete', async ($, e, next) => {
    const result = await next(e)
    const fresh = await $.session.usage()
    await update($, usage, prev => toUsage(fresh, prev))
    if (e.usage) {
      const spent = e.usage
      if (e.agentId === undefined) await update($, tokens, sum => addTokens(sum, spent))
      else await update($, agentTokens, sum => addTokens(sum, spent))
    }
    if (e.agentId !== undefined) return result

    const now = await $.clock.now()
    const n = (await read($, turns)) + 1
    await update($, turns, () => n)
    const pct = fresh.context.percent
    if (pct !== undefined) await update($, history, list => [...list, { turn: n, pct }].slice(-200))
    const five = fresh.rateLimits.find(l => l.kind === 'five_hour')
    if (five) await update($, samples, list => [...list.filter(s => now - s.t < 2 * 3_600_000), { t: now, p: five.percentUsed }])
    const before = await read($, lastTurnAt)
    await update($, lastTurnAt, () => now)
    await update($, nowAtom, () => now)
    rearmWarn($)

    if (e.reason === 'error') {
      const hit = fresh.rateLimits.find(l => l.percentUsed >= 100 && l.resetsAt)
      if (hit?.resetsAt) {
        const slot = await slotFor($, hit.resetsAt)
        const wait = Math.max(0, Date.parse(hit.resetsAt) - now) + AFTER_RESET_MS + slot * STAGGER_MS
        scheduleResume($, now + wait, wait, t.resumeText)
        $.ui.toast(t.limitHit(hhmm(now + wait)))
      } else if (retries < 1) {
        retries += 1
        scheduleResume($, now + RETRY_MS, RETRY_MS, t.retryText)
        $.ui.toast(t.retrySoon)
      }
      return result
    }
    retries = 0

    // Back after a night: a journal and a new session are cheaper than dragging the context on
    const pause = before > 0 ? now - before : 0
    if (pause > 8 * 3_600_000 && (fresh.context.tokens ?? 0) >= BIG_CONTEXT) {
      return { ...result, text: t.longPause(Math.round(pause / 3_600_000)) }
    }
    return result
  })

  // The person wrote first: the scheduled resume is no longer needed
  on('prompt.submit', async ($, e, next) => {
    if (e.origin.kind === 'composer' && (await read($, resumeAt)) > 0) await cancelResume($)
    return next(e)
  })

  on('command.run', { command: 'pult' }, async $ => ({ text: (await openPane($)) ? t.paneOpened : t.paneNoRoom }))

  on('command.run', { command: 'journal' }, async $ => {
    if (cfg.journal === '') return { text: t.journalOff }
    const path = await saveJournal($)
    return { text: path ? t.journalWritten(path) : t.journalNot }
  })

  on('command.run', { command: 'keep-cache' }, async ($, e) => ({
    text: await keepCache($, Math.min(12, Math.max(1, Number(e.args) || 3))),
  }))

  on('ui.close', { id: PANE }, async ($, e, next) => {
    isPaneOpen = false
    return next(e)
  })

  // --- the usage line in the footer ---------------------------------------------------

  on('ui.render', { component: 'SessionMode' }, async ($, e, next) => {
    const label = shortLabel(await read($, usage))
    return label ? next({ ...e, props: { ...e.props, modes: [...e.props.modes, label] } }) : next(e)
  })

  // The desktop app does not raise this one (checked on 2.1.286); there the usage line lives in the band
  on('ui.render', { component: 'PromptHint' }, async ($, e, next) => {
    if (!hintSurfaces.has(e.surface)) {
      hintSurfaces.add(e.surface)
      $.clock.after(0, () => $.ui.invalidate('ui.render'))
    }
    const line = bottomLine(await read($, usage), await read($, samples), await read($, tokens), await read($, nowAtom))
    if (line === undefined) return next(e)
    if (e.surface === 'terminal') return next({ ...e, props: { ...e.props, tail: ` · ${line}` } })
    return next({ ...e, props: { ...e.props, hint: e.props.hint ? `${line}   ${e.props.hint}` : line } })
  })

  // --- the band above the prompt: quick replies and state ---------------------------------

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const theirs = await next(e)
    if (e.props.hasSurvey) return theirs
    const { Box, Button, Text } = $.ui.resolve(e)

    const now = (await read($, nowAtom)) || (await $.clock.now())
    const u = await read($, usage)
    const due = await read($, deadline)
    const box = await read($, server)
    const last = await read($, lastTurnAt)
    const keep = await read($, keepUntil)
    const resume = await read($, resumeAt)
    const n = await read($, turns)
    const isSaved = (await read($, journalPath)) !== ''
    const left = last > 0 ? last + CACHE_MS - now : 0
    const isBig = (u?.contextTokens ?? 0) >= BIG_CONTEXT

    const info: { text: string; color?: string; dim?: boolean }[] = [{ text: place || t.noFolder, dim: true }]
    if (due !== null) {
      const d = daysBetween(localDate(now), due.date)
      const label = due.label.length > 40 ? `${due.label.slice(0, 39)}…` : due.label
      info.push({ text: `${t.due} ${ddmm(due.date)} ${label} (${days(d)})`, ...(d <= 3 ? { color: 'red' } : d <= 10 ? { color: 'yellow' } : {}) })
    }
    if (box !== null) {
      const jobs = box.jobs.map(j => `${j.name} ${span(j.minutes * 60_000)}`).join(', ')
      info.push(box.isOnline ? { text: `${cfg.serverName} ${t.serverOk}${jobs ? ` ${jobs}` : ''}`, color: 'green' } : { text: `${cfg.serverName} ${t.serverDown}`, color: 'red' })
    }
    if (keep > now) info.push({ text: t.cacheKeptUntil(hhmm(keep)), color: 'green' })
    else if (left > 0) info.push({ text: t.cacheLeft(Math.ceil(left / 60_000)), ...(left < WARN_BEFORE_MS ? { color: 'yellow' } : { dim: true }) })
    else if (last > 0 && isBig) info.push({ text: t.cacheCold, dim: true })

    const fallback = hintSurfaces.has(e.surface) ? undefined : bottomLine(u, await read($, samples), await read($, tokens), now)

    return (
      <Box flexDirection="column">
        {theirs}
        <Box flexWrap="wrap" columnGap={1}>
          {cfg.quick.map((label, i) => (
            <Button key={`q${i + 1}`} label={label} onPress={() => void $.prompt.submit({ text: label, asUser: true })} />
          ))}
        </Box>
        <Box flexWrap="wrap" columnGap={1}>
          {info.map((item, i) => (
            <Text {...(item.color ? { color: item.color } : {})} {...(item.dim ? { dimColor: true } : {})}>
              {`${i > 0 ? '· ' : ''}${item.text}`}
            </Text>
          ))}
          {resume > now && <Text color="yellow">{t.resumeAt(hhmm(resume))}</Text>}
          {resume > now && <Button key="resume-cancel" label={t.cancel} plain dimColor onPress={() => void cancelResume($)} />}
          {keep <= now && left > 0 && left < WARN_BEFORE_MS && isBig && (
            <Button key="keep" label={t.keep3h} onPress={() => void keepCache($, 3).then(text => $.ui.toast(text))} />
          )}
          {cfg.journal !== '' && !isSaved && n >= LONG_SESSION && <Text dimColor>{t.turnsNoJournal(n)}</Text>}
          {cfg.journal !== '' && !isSaved && n >= LONG_SESSION && <Button key="journal" label={t.saveJournal} onPress={() => void saveJournal($)} />}
        </Box>
        {fallback !== undefined && <Text dimColor wrap="truncate-end">{fallback}</Text>}
      </Box>
    )
  })

  // --- the pane: a feed of cards, scrolling when taller than the window ------------------------

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const table = $.ui.resolve(e)
    const { Box, Button, Text } = table
    // The terminal's table answers Svg with an empty fragment, so look at the surface
    const Svg = e.surface !== 'terminal' && 'Svg' in table ? table.Svg : undefined

    const now = (await read($, nowAtom)) || (await $.clock.now())
    const u = await read($, usage)
    const list = await read($, areaList)
    const picked = (await read($, area)) || here || (list[0]?.code ?? '')
    const info = (await read($, areas)).find(a => a.code === picked)
    const meta = list.find(a => a.code === picked)
    const wait = await read($, waiting)
    const unread = await read($, inbox)
    const mine = await read($, duties)
    const isAll = await read($, isDutiesOpen)
    const own = await read($, tokens)
    const helpers = await read($, agentTokens)
    const points = await read($, history)
    const n = await read($, turns)
    const toolCount = await read($, tools)
    const pace = u?.five ? forecast(await read($, samples), u.five.resetsAt, now) : undefined
    const resume = await read($, resumeAt)
    const last = await read($, lastTurnAt)
    const keep = await read($, keepUntil)
    const left = last > 0 ? last + CACHE_MS - now : 0
    const box = await read($, server)
    const isBusy = await read($, isPolling)
    const isSaved = (await read($, journalPath)) !== ''
    const elapsed = u && u.startedAt > 0 ? now - u.startedAt : 0

    const card = (key: string, title: string, aside: string | undefined, children: unknown[]) => (
      <Box key={key} flexDirection="column" borderStyle="round" borderDimColor paddingX={1} marginBottom={1}>
        <Box justifyContent="space-between">
          <Text bold>{title}</Text>
          {aside !== undefined && <Text dimColor>{aside}</Text>}
        </Box>
        {children}
      </Box>
    )
    const picture = (source: string, alt: string) => (Svg !== undefined ? <Svg source={source} alt={alt} /> : undefined)
    const dateRow = (key: string, date: string, label: string) => {
      const dn = daysBetween(localDate(now), date)
      return (
        <Box key={key}>
          <Box width={7} flexShrink={0}><Text dimColor>{ddmm(date)}</Text></Box>
          <Box flexGrow={1}><Text wrap="truncate-end">{label}</Text></Box>
          <Text {...dayTone(dn)}>{` ${days(dn)}`}</Text>
        </Box>
      )
    }
    const tokenText = (x: typeof own) => t.tokensLine(amount(x.input), amount(x.output), amount(x.cacheRead), amount(x.cacheWrite))

    return (
      <Box flexDirection="column">
        {list.length > 0 &&
          card('areas', t.areas, meta ? meta.folder : undefined, [
            <Box key="chips" flexWrap="wrap" columnGap={1}>
              {list.map(a => (
                <Button key={`area-${a.code}`} label={a.short} {...(a.code === picked ? { variant: 'primary' as const } : {})} onPress={() => void update($, area, () => a.code)} />
              ))}
            </Box>,
            ...(cfg.focus !== '' ? [<Text key="focus" wrap="wrap">{info?.text || t.nothingBurns}</Text>] : []),
            ...(info?.deadlines ?? []).map(d => dateRow(`d-${d.date}-${d.label}`, d.date, d.label)),
            picked !== here && meta !== undefined ? (
              <Box key="go" marginTop={1}>
                <Button key="area-go" label={t.workIn(meta.short)} onPress={() => void $.prompt.submit({ text: t.workInPrompt(meta.folder, `${cfg.areasRoot}/${meta.folder}`.replace(/\//g, isWindows() ? '\\' : '/')), asUser: true })} />
              </Box>
            ) : (
              <Text key="here" dimColor>{t.youAreHere}</Text>
            ),
          ])}

        {mine.length > 0 &&
          card('deadlines', t.myDeadlines, t.ahead(mine.length), [
            ...(isAll ? mine : mine.slice(0, SHOWN_DEADLINES)).map(d => dateRow(`dl-${d.date}-${d.what}`, d.date, isOwnRole(d.role) ? d.what : `${d.what} (${d.role})`)),
            <Box key="deadlines-actions" columnGap={1} marginTop={1}>
              {mine.length > SHOWN_DEADLINES && (
                <Button key="deadlines-more" label={isAll ? t.collapse : t.all(mine.length)} onPress={() => void update($, isDutiesOpen, v => !v)} />
              )}
              {cfg.obsidian !== '' && (
                <Button
                  key="deadlines-note"
                  label={t.openNote}
                  onPress={() => void $.process.run(opener(`obsidian://open?vault=${encodeURIComponent(cfg.obsidian)}&file=${encodeURIComponent(cfg.deadlinesNote.replace(/\.md$/, ''))}`))}
                />
              )}
            </Box>,
          ])}

        {(wait !== '' || unread > 0) &&
          card('waiting', t.waiting, unread > 0 ? t.inbox(unread) : undefined, [
            ...(wait !== '' ? [<Text key="w" wrap="wrap">{wait}</Text>] : []),
            ...(unread > 0
              ? [
                  <Box key="inbox-row" marginTop={1}>
                    <Button key="inbox" label={t.sortInbox} onPress={() => void $.prompt.submit({ text: t.sortInboxPrompt(cfg.inboxDir), asUser: true })} />
                  </Box>,
                ]
              : []),
          ])}

        {card('session', t.sessionCard, place, [
          picture(sessionSvg({ usage: u, tokens: own, agentTokens: helpers, turns: n, tools: toolCount, elapsedMs: elapsed, history: points }), `${t.context} ${Math.round(u?.contextPct ?? 0)}%, ${tokenText(own)}`) ?? (
            <Box key="session-text" flexDirection="column">
              <Text>{u ? (contextLine(u) ?? t.noData) : t.numbersLater}</Text>
              <Text dimColor>{tokenText(own)}</Text>
              {helpers.output + helpers.input > 0 && <Text dimColor>{`${t.helpers}: ${tokenText(helpers)}`}</Text>}
              <Text dimColor>{t.turnsLine(n, toolCount, span(elapsed))}</Text>
              {points.length >= 2 && <Text color="cyan">{sparkline(points.slice(-40).map(p => p.pct))}</Text>}
            </Box>
          ),
          <Box key="session-actions" flexWrap="wrap" columnGap={1} marginTop={1}>
            {cfg.journal !== '' && <Button key="pane-journal" label={isSaved ? t.journalSaved : t.saveJournal} onPress={() => void saveJournal($)} />}
            <Button key="compact" label={t.compact} onPress={() => void $.command.run({ command: 'compact' })} />
          </Box>,
        ])}

        {card('limits', t.limits, u?.costUsd !== undefined ? t.apiPrice(u.costUsd.toFixed(2)) : undefined, [
          picture(limitsSvg(u, pace, now), `${t.fiveHoursTitle} ${Math.round(u?.five?.pct ?? 0)}%, ${t.weekTitle} ${Math.round(u?.week?.pct ?? 0)}%`) ?? (
            <Box key="limits-text" flexDirection="column">
              <Text>{limitLine(t.fiveHours, u?.five, now, pace) ?? t.noDataFor(t.fiveHours)}</Text>
              <Text>{limitLine(t.week, u?.week, now) ?? t.noDataFor(t.week)}</Text>
            </Box>
          ),
          ...(resume > now
            ? [
                <Box key="resume" columnGap={1}>
                  <Text color="yellow">{t.resumeAt(hhmm(resume)).replace(/^· /, '')}</Text>
                  <Button key="pane-resume-cancel" label={t.cancel} onPress={() => void cancelResume($)} />
                </Box>,
              ]
            : []),
        ])}

        {card('cache', t.cache, undefined, [
          picture(cacheSvg(left, keep, now), keep > now ? t.cacheKeptUntil(hhmm(keep)) : left > 0 ? t.cacheLeft(Math.ceil(left / 60_000)) : t.cacheCold) ?? (
            <Text key="cache-text">{keep > now ? t.cacheKept(hhmm(keep)) : left > 0 ? t.cacheWarm(Math.ceil(left / 60_000)) : t.cacheColdLong}</Text>
          ),
          <Box key="cache-actions" columnGap={1} marginTop={1}>
            {keep > now ? (
              <Button key="release" label={t.release} onPress={() => void releaseCache($)} />
            ) : (
              <Button key="pane-keep" label={t.keep} onPress={() => void keepCache($, 3).then(text => $.ui.toast(text))} />
            )}
          </Box>,
        ])}

        {cfg.host !== '' &&
          card('server', cfg.serverName, box?.isOnline ? t.online : box ? t.offline('').replace(/: $/, '') : undefined, [
            picture(serverSvg(box, isBusy), box?.isOnline ? `${cfg.serverName}: ${t.online}, ${t.cpu} ${box.cpu ?? 0}%` : `${cfg.serverName}: ${t.noData}`) ?? (
              <Text key="server-text" {...(box?.isOnline ? { color: 'green' } : { color: 'red' })}>
                {box === null ? t.noData : box.isOnline ? `● ${t.cpu} ${box.cpu ?? 0}% · ${t.gpu} ${box.gpu?.util ?? 0}%` : `○ ${box.error ?? ''}`}
              </Text>
            ),
            ...(box?.isOnline ? [<Text key="jobs" wrap="wrap">{box.jobs.length > 0 ? t.running(box.jobs.map(j => `${j.name} ${span(j.minutes * 60_000)}`).join(', ')) : t.idle}</Text>] : []),
            <Box key="server-actions" columnGap={1} marginTop={1}>
              <Button key="refresh" label={isBusy ? t.checking : t.refresh} onPress={() => void pollServer($, true)} />
              <Button key="terminal" label={t.terminal} onPress={() => void $.process.run(terminalArgv())} />
            </Box>,
          ])}
      </Box>
    )
  })
}

