import type { PultArea, PultAreaFolder } from '../types'
import { parseDeadlines } from './deadlines'

// Work areas: folders named «NN Name» (Johnny.Decimal) under the areas root
export function areasFrom(names: string[]): PultAreaFolder[] {
  return names
    .map(name => name.match(/^(\d\d) (.+)$/))
    .filter((m): m is RegExpMatchArray => m !== null)
    .map(m => {
      const name = m[2] ?? ''
      return { code: m[1] ?? '', folder: m[0], short: name.length <= 12 ? name : (name.split(/\s+/)[0] ?? name) }
    })
    .sort((a, b) => a.code.localeCompare(b.code))
}

// Area code of the working directory: «…/40 Science/44 Patents» under the root → «40»
export function areaOf(cwd: string, root: string): string {
  const norm = (p: string) => p.replace(/\\/g, '/').replace(/\/+$/, '').toLowerCase()
  const here = norm(cwd)
  const base = norm(root)
  if (base === '' || !here.startsWith(`${base}/`)) return ''
  return cwd.replace(/\\/g, '/').slice(root.replace(/\\/g, '/').replace(/\/+$/, '').length + 1).split('/')[0]?.match(/^(\d\d) /)?.[1] ?? ''
}

// Links [[name]] become the name; no asterisks or backticks
const plain = (s: string): string =>
  s
    .replace(/\s*\(\s*\[\[[^()]*\]\]\s*\)/g, '')
    .replace(/\[\[([^\]|]+)(\|([^\]]+))?\]\]/g, (_, name: string, __, alias?: string) => alias ?? name)
    .replace(/[*`]/g, '')
    .replace(/\s{2,}/g, ' ')
    .trim()

// The focus note: «- **40 Science.** …» or «- **10, project.** …» belongs to the area by its first two digits;
// a bold line without a code («- **Waiting:** …») goes to the waiting card
export function parseAreas(note: string, today: string, codes: string[]): { areas: PultArea[]; waiting: string } {
  const lines = note.split('\n').filter(l => l.startsWith('- **'))
  const waiting: string[] = []
  const byCode = new Map<string, string[]>()
  for (const line of lines) {
    const head = line.match(/^- \*\*([^*]+)\*\*\s*(.*)$/)
    if (!head) continue
    const title = (head[1] ?? '').trim()
    const body = head[2] ?? ''
    const code = title.match(/^(\d\d)\b/)?.[1]
    if (code === undefined) {
      waiting.push(plain(body))
      continue
    }
    // «10 Admissions.» is the area itself; «10, project.» names a project inside it
    const extra = title.match(/^\d\d,\s*(.+?)\.?$/)?.[1]
    byCode.set(code, [...(byCode.get(code) ?? []), (extra ? `${extra}: ` : '') + plain(body)])
  }
  const areas = codes.map(code => {
    const raw = lines.filter(l => l.match(/^- \*\*(\d\d)/)?.[1] === code).join('\n')
    return { code, text: (byCode.get(code) ?? []).join('\n'), deadlines: parseDeadlines(raw, today).slice(0, 5) }
  })
  return { areas, waiting: waiting.filter(Boolean).join('\n') }
}

