import type { PultDeadline as Deadline } from '../types'

const RU = ['января', 'февраля', 'марта', 'апреля', 'мая', 'июня', 'июля', 'августа', 'сентября', 'октября', 'ноября', 'декабря']
const EN = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september', 'october', 'november', 'december']
const EN3 = EN.map(m => m.slice(0, 3))
const MONTH = [...RU, ...EN, ...EN3].join('|')

// 2026-12-07 | 07.11 and 07.11.2026 | 4 ноября 2026, 8-11 октября, 8 October 2026 (first day) | October 8, Oct 8 2026
const DATE = new RegExp(
  String.raw`\b(20\d\d)-(\d\d)-(\d\d)\b` +
    String.raw`|\b(\d\d)\.(\d\d)(?:\.(20\d\d))?\b` +
    String.raw`|\b(\d{1,2})(?:[-–]\d{1,2})?\s+(${MONTH})\.?(?:\s+(20\d\d))?` +
    String.raw`|\b(${[...EN, ...EN3].join('|')})\.?\s+(\d{1,2})(?:st|nd|rd|th)?(?:,?\s+(20\d\d))?`,
  'gi',
)
const FILLER = /^(до|срок|официальный|дедлайн|к|с|по|после|by|due|until|till|deadline|on|before|after|from)$/i
const DAY = 86_400_000

const pad = (n: number): string => String(n).padStart(2, '0')

export const daysBetween = (from: string, to: string): number => Math.round((Date.parse(to) - Date.parse(from)) / DAY)

function monthOf(name: string): number {
  const low = name.toLowerCase()
  const at = [RU, EN, EN3].map(list => list.indexOf(low)).find(i => i >= 0)
  return (at ?? -1) + 1
}

function toIso(m: RegExpMatchArray, today: string): string | undefined {
  const year = (y: string | undefined) => [Number(y ?? today.slice(0, 4)), y !== undefined] as const
  let y: number
  let mo: number
  let d: number
  let hasYear: boolean
  if (m[1]) {
    ;[y, mo, d, hasYear] = [Number(m[1]), Number(m[2]), Number(m[3]), true]
  } else if (m[4]) {
    ;[[y, hasYear], mo, d] = [year(m[6]), Number(m[5]), Number(m[4])]
  } else if (m[7]) {
    ;[[y, hasYear], mo, d] = [year(m[9]), monthOf(m[8] ?? ''), Number(m[7])]
  } else {
    ;[[y, hasYear], mo, d] = [year(m[12]), monthOf(m[10] ?? ''), Number(m[11])]
  }
  if (mo < 1 || mo > 12 || d < 1 || d > 31) return undefined
  // A date without a year that is more than half a year in the past belongs to next year
  if (!hasYear && daysBetween(today, `${y}-${pad(mo)}-${pad(d)}`) < -180) y += 1
  return `${y}-${pad(mo)}-${pad(d)}`
}

// Words without trailing «by», «due», «до», «срок» and punctuation
function trimmed(text: string): string {
  const words = text.replace(/^[\s,:;]+/, '').split(/\s+/).filter(Boolean)
  while (words.length > 0 && FILLER.test(words[words.length - 1] ?? '')) words.pop()
  return words.join(' ').replace(/[\s,:;]+$/, '')
}

// Label: the last piece of the phrase before the date (after a comma, colon or bracket);
// with nothing before the date, the words after it up to a comma
function labelOf(clause: string, from: number, start: number, end: number): string {
  const head = clause.slice(from, start).replace(/\*\*/g, '')
  const before = trimmed(head.split(/[,:;()]/).pop() ?? '') || trimmed(head)
  return before || (clause.slice(end).replace(/\*\*/g, '').split(/[,:(]/)[0] ?? '').trim()
}

// Dates in the bullet lines of a note, each with the words around it, today and later, by date
export function parseDeadlines(note: string, today: string): Deadline[] {
  const found: Deadline[] = []
  for (const raw of note.split('\n')) {
    if (!raw.startsWith('- ')) continue
    const line = raw
      .slice(2)
      .replace(/^\*\*[^*]*\*\*\s*/, '')
      .replace(/\(\s*\[\[[^\]]*\]\](\s*,\s*\[\[[^\]]*\]\])*\s*\)/g, '')
      .replace(/\[\[[^\]]*\]\]/g, '')
      .replace(/`/g, '')

    for (const clause of line.split(/;|\.\s+/)) {
      let from = 0
      for (const m of clause.matchAll(DATE)) {
        const start = m.index ?? 0
        const end = start + m[0].length
        const date = toIso(m, today)
        if (date !== undefined && date >= today) found.push({ date, label: labelOf(clause, from, start, end) })
        from = end
      }
    }
  }
  return found.filter(item => item.label !== '').sort((a, b) => a.date.localeCompare(b.date))
}

files.hooks/duties.ts:
import type { PultDuty } from '../types'

// A deadlines table: rows like «| 2026-12-06 | what to do | window | role |», today and later, by date
export function parseDuties(note: string, today: string): PultDuty[] {
  const rows: PultDuty[] = []
  for (const line of note.split('\n')) {
    const cells = line.trim().replace(/^\||\|$/g, '').split('|').map(c => c.trim())
    const [date = '', what = '', window = '', role = ''] = cells
    if (!/^20\d\d-\d\d-\d\d$/.test(date) || what === '' || date < today) continue
    rows.push({ date, what, window, role })
  }
  return rows.sort((a, b) => a.date.localeCompare(b.date))
}

// A role that means «mine» is not worth repeating on every row
export const isOwnRole = (role: string): boolean => role === '' || /^(отв|owner|lead|me\b|mine)/i.test(role)

