import type { SessionUsage } from 'claude-code'

import type { PultSample, PultTokens, PultUsage } from '../types'
import { t } from './i18n'

// The machine's own UTC offset at that moment
const shift = (ms: number): number => -new Date(ms).getTimezoneOffset() * 60_000

export const hhmm = (ms: number): string => new Date(ms + shift(ms)).toISOString().slice(11, 16)
export const localDate = (ms: number): string => new Date(ms + shift(ms)).toISOString().slice(0, 10)
export const localStamp = (ms: number): string => new Date(ms + shift(ms)).toISOString()
export const ddmm = (iso: string): string => `${iso.slice(8, 10)}.${iso.slice(5, 7)}`

// Reset time in local time; not today - with the date
export function resetAt(iso: string, now: number): string {
  const at = Date.parse(iso)
  return localDate(at) === localDate(now) ? hhmm(at) : `${ddmm(localDate(at))} ${hhmm(at)}`
}

const isEnglish = (): boolean => t.thousand === 'k'

const decimal = (n: number): string => {
  const s = n.toFixed(1).replace(/\.0$/, '')
  return isEnglish() ? s : s.replace('.', ',')
}

// 950 · 82k · 1.2M (ru: 82 тыс. · 1,2 млн)
export function amount(n: number): string {
  const sep = isEnglish() ? '' : ' '
  if (n >= 1_000_000) return `${decimal(n / 1_000_000)}${sep}${t.million}`
  if (n >= 1000) return `${Math.round(n / 1000)}${sep}${t.thousand}`
  return String(n)
}

export function span(ms: number): string {
  const minutes = Math.max(0, Math.round(ms / 60_000))
  return minutes >= 60 ? `${Math.floor(minutes / 60)} ${t.hours} ${minutes % 60} ${t.minutes}` : `${minutes} ${t.minutes}`
}

export const days = (n: number): string => (n === 0 ? t.today : n === 1 ? t.tomorrow : t.days(n))

export const EMPTY_TOKENS: PultTokens = { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 }

export function toUsage(u: Pick<SessionUsage, 'context' | 'rateLimits' | 'cost'> & { startedAt?: number }, before: PultUsage | null): PultUsage {
  const limit = (kind: string) => {
    const found = u.rateLimits.find(l => l.kind === kind)
    return found ? { pct: found.percentUsed, ...(found.resetsAt ? { resetsAt: found.resetsAt } : {}) } : undefined
  }
  const five = limit('five_hour')
  const week = limit('seven_day')
  return {
    startedAt: u.startedAt ?? before?.startedAt ?? 0,
    window: u.context.window,
    ...(u.context.tokens !== undefined ? { contextTokens: u.context.tokens } : {}),
    ...(u.context.percent !== undefined ? { contextPct: u.context.percent } : {}),
    ...(five ? { five } : {}),
    ...(week ? { week } : {}),
    ...(u.cost ? { costUsd: u.cost.usd } : {}),
  }
}

// Forecast for the five-hour window from the pace over the last hour
export function forecast(points: PultSample[], resetsAt: string | undefined, now: number): string | undefined {
  const recent = points.filter(s => now - s.t <= 60 * 60_000)
  const first = recent[0]
  const last = recent[recent.length - 1]
  if (first === undefined || last === undefined || recent.length < 2) return undefined
  const dt = last.t - first.t
  const dp = last.p - first.p
  if (dt < 5 * 60_000 || dp <= 0) return undefined
  const at = last.t + ((100 - last.p) / dp) * dt
  if (resetsAt && at >= Date.parse(resetsAt)) return t.enough
  return t.pace(hhmm(at))
}

export function contextLine(u: PultUsage): string | undefined {
  if (u.contextPct === undefined) return undefined
  const used = u.contextTokens ?? 0
  return `${t.context} ${Math.round(u.contextPct)}%, ${amount(used)} ${t.of} ${amount(u.window)}, ${t.free} ${amount(Math.max(0, u.window - used))}`
}

type PultLimit = NonNullable<PultUsage['five']>

export function limitLine(label: string, l: PultLimit | undefined, now: number, pace?: string): string | undefined {
  if (l === undefined) return undefined
  const parts = [`${label} ${Math.round(l.pct)}%`.trim()]
  if (l.resetsAt) parts.push(`${t.resets} ${resetAt(l.resetsAt, now)}`)
  if (pace) parts.push(pace)
  return parts.join(', ')
}

// The usage line: context, both limits, what the session spent
export function bottomLine(u: PultUsage | null, samples: PultSample[], tokens: PultTokens, now: number): string | undefined {
  if (u === null) return undefined
  const five = u.five ? limitLine(t.fiveHours, u.five, now, forecast(samples, u.five.resetsAt, now)) : undefined
  const spent = tokens.output + tokens.input + tokens.cacheWrite > 0 ? t.session(amount(tokens.output), amount(tokens.cacheRead)) : undefined
  const parts = [contextLine(u), five, limitLine(t.week, u.week, now), spent].filter((p): p is string => p !== undefined)
  return parts.length > 0 ? parts.join(' · ') : undefined
}

// Short label for the footer modes: «context 41% · 5 h 63%»
export function shortLabel(u: PultUsage | null): string | undefined {
  if (u === null) return undefined
  const parts = [u.contextPct !== undefined ? `${t.context} ${Math.round(u.contextPct)}%` : undefined, u.five ? `${t.fiveHours} ${Math.round(u.five.pct)}%` : undefined]
  const shown = parts.filter((p): p is string => p !== undefined)
  return shown.length > 0 ? shown.join(' · ') : undefined
}

export function addTokens(sum: PultTokens, u: { input_tokens: number; output_tokens: number; cache_read_input_tokens: number; cache_creation_input_tokens: number }): PultTokens {
  return {
    input: sum.input + u.input_tokens,
    output: sum.output + u.output_tokens,
    cacheRead: sum.cacheRead + u.cache_read_input_tokens,
    cacheWrite: sum.cacheWrite + u.cache_creation_input_tokens,
  }
}

export const norm = (p: string): string => p.replace(/\\/g, '/').replace(/\/+$/, '')

// Where the session runs: the path under the areas folder, or the last folder name
export function placeOf(cwd: string, areasRoot: string): string {
  const here = norm(cwd)
  const root = norm(areasRoot)
  if (root !== '' && here.toLowerCase().startsWith(`${root.toLowerCase()}/`)) {
    return here.slice(root.length + 1).split('/').slice(0, 3).join(' › ')
  }
  return here.split('/').pop() ?? cwd
}

// ▁▂▃▅▇ by percent, for the terminal, which has no Svg
export function sparkline(values: number[]): string {
  const marks = '▁▂▃▄▅▆▇█'
  return values.map(v => marks[Math.min(marks.length - 1, Math.max(0, Math.floor((v / 100) * marks.length)))] ?? '▁').join('')
}

