import type { PultServer } from '../types'

const KB_IN_GB = 1024 * 1024
// Process names counted as heavy work
const JOBS = ['python', 'pythonw', 'blender', 'UnrealEditor*', 'ffmpeg', 'ollama', 'whisper*']

// Runs on a Windows machine in PowerShell 5.1 and prints one key=value line
const POWERSHELL = [
  "$ErrorActionPreference='SilentlyContinue'; $ProgressPreference='SilentlyContinue'",
  '$c=[int](Get-CimInstance Win32_Processor | Measure-Object LoadPercentage -Average).Average',
  '$o=Get-CimInstance Win32_OperatingSystem',
  "$g=(& nvidia-smi --query-gpu=utilization.gpu,memory.used,memory.total,temperature.gpu --format=csv,noheader,nounits | Select-Object -First 1) -replace ' ',''",
  '$now=Get-Date',
  `$j=(Get-Process ${JOBS.join(',')} | Where-Object StartTime | ForEach-Object { $_.ProcessName+'@'+[int]($now-$_.StartTime).TotalMinutes }) -join ','`,
  '"cpu=$c;ramfree=$($o.FreePhysicalMemory);ramtotal=$($o.TotalVisibleMemorySize);gpu=$g;jobs=$j"',
].join('\n')

// Runs on Linux in sh and prints the same line
const SH = [
  // procps prints «95.6 id», older top «95.6%id»
  "c=$(top -bn1 | awk -F'[ ,]+' '/^%?Cpu/ {for(i=1;i<=NF;i++){if($i==\"id\"){print int(100-$(i-1)); exit} if($i ~ /%id$/){sub(/%id$/,\"\",$i); print int(100-$i); exit}}}')",
  // MemAvailable since Linux 3.14, MemFree before it
  "t=$(awk '/MemTotal/ {print $2}' /proc/meminfo); f=$(awk '/MemAvailable/ {print $2}' /proc/meminfo); [ -n \"$f\" ] || f=$(awk '/MemFree/ {print $2}' /proc/meminfo)",
  "g=$(nvidia-smi --query-gpu=utilization.gpu,memory.used,memory.total,temperature.gpu --format=csv,noheader,nounits 2>/dev/null | head -1 | tr -d ' ')",
  `j=$(ps -eo comm=,etimes= | awk '$1 ~ /^(${JOBS.map(j => j.replace('*', '')).join('|')})/ {printf "%s%s@%d", s, $1, $2/60; s=","}')`,
  'echo "cpu=$c;ramfree=$f;ramtotal=$t;gpu=$g;jobs=$j"',
].join('\n')

// -EncodedCommand expects UTF-16LE in base64: the script passes through ssh without quoting trouble
function encode(script: string): string {
  let bytes = ''
  for (let i = 0; i < script.length; i += 1) {
    const code = script.charCodeAt(i)
    bytes += String.fromCharCode(code & 0xff, code >> 8)
  }
  return btoa(bytes)
}

export function probeArgv(host: string, shell: string): string[] {
  const base = ['ssh', '-o', 'BatchMode=yes', '-o', 'ConnectTimeout=5', host]
  return shell === 'powershell' ? [...base, 'powershell', '-NoProfile', '-EncodedCommand', encode(POWERSHELL)] : [...base, SH]
}

export function offline(checkedAt: number, error: string): PultServer {
  return { isOnline: false, checkedAt, jobs: [], error }
}

// The last meaningful line of an ssh error, without key exchange warnings
export function sshError(stderr: string): string {
  const lines = stderr.split(/\r?\n/).map(line => line.trim()).filter(line => line !== '' && !line.startsWith('**'))
  return lines[lines.length - 1] ?? 'ssh failed'
}

export function parseProbe(stdout: string, checkedAt: number): PultServer | undefined {
  const line = stdout.split(/\r?\n/).find(one => one.startsWith('cpu='))
  if (line === undefined) return undefined

  const field = new Map(
    line.split(';').map(pair => {
      const at = pair.indexOf('=')
      return [pair.slice(0, at), pair.slice(at + 1)] as const
    }),
  )
  const ramFree = Number(field.get('ramfree')) / KB_IN_GB
  const ramTotal = Number(field.get('ramtotal')) / KB_IN_GB
  const [util, memUsed, memTotal, tempC] = (field.get('gpu') ?? '').split(',').map(Number)
  const jobs = (field.get('jobs') ?? '')
    .split(',')
    .filter(Boolean)
    .map(job => {
      const [name = '', minutes = '0'] = job.split('@')
      return { name, minutes: Number(minutes) }
    })

  return {
    isOnline: true,
    checkedAt,
    cpu: Number(field.get('cpu')) || 0,
    ...(ramTotal > 0 ? { ramUsedGb: ramTotal - ramFree, ramTotalGb: ramTotal } : {}),
    ...(util !== undefined && memUsed !== undefined && memTotal !== undefined && tempC !== undefined && memTotal > 0
      ? { gpu: { util, memUsedGb: memUsed / 1024, memTotalGb: memTotal / 1024, tempC } }
      : {}),
    jobs,
  }
}

