// Pult cards for the desktop app: SVG on its own dark background, readable in light and dark themes alike

import type { PultPoint, PultServer, PultTokens, PultUsage } from '../types'
import { amount, hhmm, resetAt, span } from './format'
import { t } from './i18n'

const W = 560
const FONT = "'Segoe UI', Inter, system-ui, sans-serif"
export const C = {
  bg: '#14171c',
  edge: '#272c34',
  ink: '#e6e8eb',
  muted: '#8b93a1',
  track: '#2a3038',
  blue: '#58a6ff',
  clay: '#e8875b',
  green: '#3fb950',
  yellow: '#d29922',
  red: '#f85149',
  violet: '#a371f7',
}

const esc = (s: string): string => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')

export const tone = (pct: number, calm = C.green): string => (pct >= 85 ? C.red : pct >= 60 ? C.yellow : calm)

function text(x: number, y: number, s: string, size: number, fill: string, extra = ''): string {
  return `<text x="${x}" y="${y}" font-size="${size}" fill="${fill}" ${extra}>${esc(s)}</text>`
}

function frame(h: number, body: string): string {
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${h}" width="${W}" height="${h}" font-family="${FONT}"><rect x="0.5" y="0.5" width="${W - 1}" height="${h - 1}" rx="14" fill="${C.bg}" stroke="${C.edge}"/>${body}</svg>`
}

// A ring: an arc by share, the label in the middle
function ring(cx: number, cy: number, r: number, pct: number, color: string, width: number): string {
  const len = 2 * Math.PI * r
  const on = (Math.min(100, Math.max(0, pct)) / 100) * len
  return `<circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="${C.track}" stroke-width="${width}"/><circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="${color}" stroke-width="${width}" stroke-linecap="round" stroke-dasharray="${on.toFixed(1)} ${len.toFixed(1)}" transform="rotate(-90 ${cx} ${cy})"/>`
}

// A half-circle gauge
function gauge(cx: number, cy: number, r: number, pct: number, color: string): string {
  const len = Math.PI * r
  const on = (Math.min(100, Math.max(0, pct)) / 100) * len
  const d = `M${cx - r},${cy} A${r},${r} 0 0 1 ${cx + r},${cy}`
  return `<path d="${d}" fill="none" stroke="${C.track}" stroke-width="12" stroke-linecap="round"/><path d="${d}" fill="none" stroke="${color}" stroke-width="12" stroke-linecap="round" stroke-dasharray="${on.toFixed(1)} ${len.toFixed(1)}"/>`
}

function bar(x: number, y: number, w: number, pct: number, color: string, h = 8): string {
  const on = Math.max(0, Math.min(1, pct / 100)) * w
  return `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${h / 2}" fill="${C.track}"/><rect x="${x}" y="${y}" width="${on.toFixed(1)}" height="${h}" rx="${h / 2}" fill="${color}"/>`
}

export type SessionCard = {
  usage: PultUsage | null
  tokens: PultTokens
  agentTokens: PultTokens
  turns: number
  tools: number
  elapsedMs: number
  history: PultPoint[]
}

export function sessionSvg(s: SessionCard): string {
  const pct = s.usage?.contextPct ?? 0
  const used = s.usage?.contextTokens ?? 0
  const win = s.usage?.window ?? 0
  const color = pct >= 85 ? C.red : pct >= 70 ? C.yellow : C.blue
  const rows: [string, number, string][] = [
    [t.input, s.tokens.input, C.blue],
    [t.output, s.tokens.output, C.clay],
    [t.cacheRead, s.tokens.cacheRead, C.green],
    [t.cacheWrite, s.tokens.cacheWrite, C.violet],
  ]
  const top = Math.max(1, ...rows.map(r => r[1]))
  const table = rows
    .map(([label, n, c], i) => {
      const y = 44 + i * 30
      // A log scale, so thousands of output tokens still show beside millions of cache reads
      const share = n > 0 ? (Math.log10(n + 1) / Math.log10(top + 1)) * 100 : 0
      return text(196, y, label, 13, C.muted) + text(W - 20, y, amount(n), 14, C.ink, 'text-anchor="end" font-weight="600"') + bar(196, y + 7, W - 216, share, c, 5)
    })
    .join('')
  const meta =
    text(196, 166, t.turnsLine(s.turns, s.tools, span(s.elapsedMs)), 12, C.muted) +
    (s.agentTokens.output + s.agentTokens.input > 0 ? text(196, 184, t.helpersLine(amount(s.agentTokens.input), amount(s.agentTokens.output)), 12, C.muted) : '')

  const pts = s.history.slice(-60)
  let chart = text(20, 236, t.growthLater, 12, C.muted)
  if (pts.length >= 2) {
    const x0 = 20
    const x1 = W - 20
    const y0 = 292
    const y1 = 228
    const first = pts[0]?.turn ?? 0
    const lastTurn = pts[pts.length - 1]?.turn ?? 1
    const x = (n: number) => x0 + ((n - first) / Math.max(1, lastTurn - first)) * (x1 - x0)
    const y = (p: number) => y0 - (Math.min(100, p) / 100) * (y0 - y1)
    const line = pts.map((p, i) => `${i === 0 ? 'M' : 'L'}${x(p.turn).toFixed(1)},${y(p.pct).toFixed(1)}`).join(' ')
    chart =
      `<defs><linearGradient id="g" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${C.blue}" stop-opacity="0.45"/><stop offset="1" stop-color="${C.blue}" stop-opacity="0"/></linearGradient></defs>` +
      `<line x1="${x0}" x2="${x1}" y1="${y(50)}" y2="${y(50)}" stroke="${C.track}" stroke-dasharray="3 5"/>` +
      `<path d="${line} L${x(lastTurn).toFixed(1)},${y0} L${x0},${y0} Z" fill="url(#g)"/>` +
      `<path d="${line}" fill="none" stroke="${C.blue}" stroke-width="2"/>` +
      text(x0, y1 - 8, t.growth, 12, C.muted) +
      text(x1, y1 - 8, t.turnRange(first, lastTurn), 12, C.muted, 'text-anchor="end"')
  }
  return frame(
    306,
    ring(92, 92, 62, pct, color, 14) +
      text(92, 96, `${Math.round(pct)}%`, 30, C.ink, 'text-anchor="middle" font-weight="700"') +
      text(92, 118, t.ofContext, 12, C.muted, 'text-anchor="middle"') +
      text(92, 182, win > 0 ? `${amount(used)} ${t.of} ${amount(win)}` : t.waitingFirst, 12, C.muted, 'text-anchor="middle"') +
      text(196, 22, t.sessionTokens, 12, C.muted) +
      table +
      meta +
      chart,
  )
}

export function limitsSvg(u: PultUsage | null, pace: string | undefined, now: number): string {
  const one = (cx: number, title: string, l: PultUsage['five'], note?: string): string => {
    if (l === undefined) return text(cx, 90, t.noDataFor(title), 13, C.muted, 'text-anchor="middle"')
    return (
      gauge(cx, 96, 70, l.pct, tone(l.pct, C.clay)) +
      text(cx, 86, `${Math.round(l.pct)}%`, 28, C.ink, 'text-anchor="middle" font-weight="700"') +
      text(cx, 120, title, 13, C.muted, 'text-anchor="middle"') +
      (l.resetsAt ? text(cx, 140, t.resetAt(resetAt(l.resetsAt, now)), 12, C.muted, 'text-anchor="middle"') : '') +
      (note ? text(cx, 158, note, 12, note === t.enough ? C.green : C.yellow, 'text-anchor="middle"') : '')
    )
  }
  return frame(172, one(W / 4, t.fiveHoursTitle, u?.five, pace) + one((3 * W) / 4, t.weekTitle, u?.week))
}

export function cacheSvg(leftMs: number, keepUntil: number, now: number): string {
  let label: string
  let color: string
  let pct: number
  if (keepUntil > now) {
    label = t.cacheKept(hhmm(keepUntil))
    color = C.green
    pct = 100
  } else if (leftMs > 0) {
    const minutes = Math.ceil(leftMs / 60_000)
    label = t.cacheWarm(minutes)
    color = minutes <= 10 ? C.yellow : C.blue
    pct = (leftMs / 3_600_000) * 100
  } else {
    label = t.cacheColdLong
    color = C.muted
    pct = 0
  }
  return frame(70, text(20, 30, t.cacheTitle, 13, C.muted) + text(W - 20, 30, label, 14, C.ink, 'text-anchor="end" font-weight="600"') + bar(20, 44, W - 40, pct, color, 10))
}

export function serverSvg(s: PultServer | null, isBusy: boolean): string {
  const head =
    s === null
      ? text(20, 30, isBusy ? t.checkingLink : t.noData, 14, C.muted)
      : s.isOnline
        ? `<circle cx="26" cy="25" r="6" fill="${C.green}"/>` + text(40, 30, t.online, 14, C.ink, 'font-weight="600"')
        : `<circle cx="26" cy="25" r="6" fill="${C.red}"/>` + text(40, 30, t.offline((s.error ?? '').slice(0, 60)), 13, C.ink)
  const checked = s !== null ? text(W - 20, 30, isBusy ? t.checking : t.checkedAt(hhmm(s.checkedAt)), 12, C.muted, 'text-anchor="end"') : ''
  if (s === null || !s.isOnline) return frame(52, head + checked)
  const gb = (v: number) => (t.gb === 'GB' ? v.toFixed(1) : v.toFixed(1).replace('.', ','))
  const cells: [string, number, string][] = [
    [t.cpu, s.cpu ?? 0, ''],
    [t.ram, s.ramUsedGb !== undefined && s.ramTotalGb ? (s.ramUsedGb / s.ramTotalGb) * 100 : 0, s.ramUsedGb !== undefined && s.ramTotalGb !== undefined ? `${gb(s.ramUsedGb)}/${gb(s.ramTotalGb)} ${t.gb}` : '-'],
    [t.gpu, s.gpu?.util ?? 0, s.gpu ? `${s.gpu.tempC}°C` : '-'],
    [t.vram, s.gpu ? (s.gpu.memUsedGb / s.gpu.memTotalGb) * 100 : 0, s.gpu ? `${gb(s.gpu.memUsedGb)}/${gb(s.gpu.memTotalGb)} ${t.gb}` : '-'],
  ]
  const rings = cells
    .map(([label, pct, value], i) => {
      const cx = 70 + i * 140
      return ring(cx, 96, 38, pct, tone(pct), 9) + text(cx, 102, `${Math.round(pct)}%`, 17, C.ink, 'text-anchor="middle" font-weight="700"') + text(cx, 154, label, 12, C.muted, 'text-anchor="middle"') + text(cx, 172, value, 12, C.ink, 'text-anchor="middle"')
    })
    .join('')
  return frame(190, head + checked + rings)
}

