export type PultLimit = { pct: number; resetsAt?: string }

export type PultUsage = {
  startedAt: number
  window: number
  contextTokens?: number
  contextPct?: number
  five?: PultLimit
  week?: PultLimit
  costUsd?: number
}

export type PultSample = { t: number; p: number }

export type PultTokens = { input: number; output: number; cacheRead: number; cacheWrite: number }

export type PultPoint = { turn: number; pct: number }

export type PultDeadline = { date: string; label: string }

// One area of the focus note and its dates
export type PultArea = { code: string; text: string; deadlines: PultDeadline[] }

// One row of the deadlines table
export type PultDuty = { date: string; what: string; window: string; role: string }

// A work area folder «NN Name»
export type PultAreaFolder = { code: string; folder: string; short: string }

export type PultJob = { name: string; minutes: number }

export type PultServer = {
  isOnline: boolean
  checkedAt: number
  cpu?: number
  ramUsedGb?: number
  ramTotalGb?: number
  gpu?: { util: number; memUsedGb: number; memTotalGb: number; tempC: number }
  jobs: PultJob[]
  error?: string
}

declare module 'claude-code' {
  interface PluginState {
    pult: {
      usage: PultUsage | null
      samples: PultSample[]
      turns: number
      tools: number
      tokens: PultTokens
      agentTokens: PultTokens
      history: PultPoint[]
      lastTurnAt: number
      now: number
      keepUntil: number
      resumeAt: number
      journalPath: string
      server: PultServer | null
      isPolling: boolean
      deadline: PultDeadline | null
      areas: PultArea[]
      waiting: string
      inbox: number
      area: string
      areaList: PultAreaFolder[]
      duties: PultDuty[]
      isDutiesOpen: boolean
    }
  }
}
